   324  /* Decrypts a PKCS #7 encryptedData. The output is allocated
   325   * and stored in dec.
   326   */
   327  int
   328  _gnutls_pkcs7_decrypt_data(const gnutls_datum_t * data,
   329                             const char *password, gnutls_datum_t * dec)
   330  {
   430          char enc_oid[MAX_OID_SIZE];
