   436          if ((result =
   437               asn1_create_element(_gnutls_get_pkix(),
   438                                   "PKIX1.pkcs-7-EncryptedData",
   439                                   &pkcs7_asn)) != ASN1_SUCCESS) {
   440                  gnutls_assert();
   441                  result = _gnutls_asn2err(result);
   442                  goto error;
   443          }
   444
   445          result = asn1_der_decoding(&pkcs7_asn, data->data, data->size, NULL);
   446          if (result != ASN1_SUCCESS) {
   447                  gnutls_assert();
   448                  result = _gnutls_asn2err(result);
   449                  goto error;
   450          }
   451
   452          /* Check the encryption schema OID
   453           */
   454          len = sizeof(enc_oid);
   455          result =
   456              asn1_read_value(pkcs7_asn,
   457                              "encryptedContentInfo.contentEncryptionAlgorithm.algorithm",
   458                              enc_oid, &len);
   459          if (result != ASN1_SUCCESS) {
   460                  gnutls_assert();
   461                  result = _gnutls_asn2err(result);
   462                  goto error;
   463          }
   464
   465          if (oid) {
   466                  *oid = gnutls_strdup(enc_oid);
   467          }
   468
   469          if ((result = _gnutls_check_pkcs_cipher_schema(enc_oid)) < 0) {
   470                  gnutls_assert();
   471                  goto error;
   472          }
   473          schema = result;
   474
   475          /* Get the DER encoding of the parameters.
   476           */
   477          result =
   478              asn1_der_decoding_startEnd(pkcs7_asn, data->data, data->size,
   479                                         "encryptedContentInfo.contentEncryptionAlgorithm.parameters",
   480                                         &params_start, &params_end);
   481          if (result != ASN1_SUCCESS) {
   482                  gnutls_assert();
   483                  result = _gnutls_asn2err(result);
   484                  goto error;
   485          }
   486          params_len = params_end - params_start + 1;
   487
   488          result =
   489              _gnutls_read_pkcs_schema_params(&schema, NULL,
   490                                              &data->data[params_start],
   491                                              params_len, kdf_params,
   492                                              &enc_params);
   493          if (result < 0) {
   494                  gnutls_assert();
   495                  goto error;
   496          }
   497
   498          *p = _gnutls_pkcs_schema_get(schema);
   499          if (*p == NULL) {
   500                  gnutls_assert();
   501                  result = GNUTLS_E_UNKNOWN_CIPHER_TYPE;
   502                  goto error;
   503          }
   504
   505          asn1_delete_structure2(&pkcs7_asn, ASN1_DELETE_FLAG_ZEROIZE);
   506
   507          return 0;
   508
   509   error:
   510          asn1_delete_structure(&pasn);
   511          asn1_delete_structure2(&pkcs7_asn, ASN1_DELETE_FLAG_ZEROIZE);
   512          return result;
   513  }
