   778  /* Reads the PBE parameters from PKCS-12 schemas (*&#%*&#% RSA).
   779   */
   780  static int read_pkcs12_kdf_params(ASN1_TYPE pasn, struct pbkdf2_params *params)
   781  {
   782          int result;
   783
   784          memset(params, 0, sizeof(*params));
   785
   786          /* read the salt */
   787          params->salt_size = sizeof(params->salt);
   788          result =
   789              asn1_read_value(pasn, "salt", params->salt, &params->salt_size);
   790          if (result != ASN1_SUCCESS) {
   791                  gnutls_assert();
   792                  return _gnutls_asn2err(result);
   793          }
   794
   795          if (params->salt_size < 0)
   796                  return gnutls_assert_val(GNUTLS_E_ILLEGAL_PARAMETER);
   797
   798          _gnutls_hard_log("salt.size: %d\n", params->salt_size);
   799
   800          /* read the iteration count
   801           */
   802          result =
   803              _gnutls_x509_read_uint(pasn, "iterations", &params->iter_count);
   804          if (result < 0)
   805                  return gnutls_assert_val(result);
   806
   807          if (params->iter_count >= MAX_ITER_COUNT || params->iter_count == 0)
   808                  return gnutls_assert_val(GNUTLS_E_ILLEGAL_PARAMETER);
   809
   810          _gnutls_hard_log("iterationCount: %d\n", params->iter_count);
   811
   812          params->key_size = 0;
   813
   814          return 0;
   815  }
